#include <cmath>

using namespace std;

int main() {
    int g, h;
    int product = 21 * pow(d, 4) - 44 * pow(d, 3) - 35 * pow(d, 2) + 14 * d - 16;

    // Calculate g and h
    g = product - (7 * pow(d, 2) - 3 * d + g) * (3 * pow(d, 2) + h * d - 8);
    h = product - (7 * pow(d, 2) - 3 * d + g) * (3 * pow(d, 2) + h * d - 8);

    // Print the sum of g and h
    cout << "g + h = " << g + h << endl;

    return 0;
}

