double x_rotated = -x;
double y_rotated = -y;

// Shift 3 units to the left
double x_shifted = x_rotated - 3;

// Shift 2 units down
double y_shifted = y_rotated - 2;

// Find the zeros of the parabola
double zero_1 = sqrt(y_shifted);
double zero_2 = -sqrt(y_shifted);

// Calculate a and b
a = zero_1;
b = zero_2;

// Calculate a+b
double a_plus_b = a + b;

cout << "a+b = " << a_plus_b << endl;

return 0;
}

